// Wrike on a permanent access token: every operation of Wrike's API v4 (tasks, folders, projects, spaces, comments,
// attachments, time, approvals, bookings, blueprints, custom fields, workflows, users and the admin calls), plus the
// webhook calls and file uploads its spec leaves out. actions.json is generated by `bun scripts/openapi-actions.ts wrike`.
// Wrike keeps each account in one data centre (www, app-eu or app-us2.wrike.com), so the key can start with where:
// "eu:<token>". Triggers: a webhook for every event Wrike sends (triggers.ts); new people and spaces are polled.
import { z } from "zod";
import { AppFile, AppsError } from "../../types";
import type { OwnAction, OwnApp } from "../index";
import { type Api, call, type Send, specActions } from "../openapi";
import { events, receive, triggers, unwatch, wanted, watch } from "./triggers";

const HOSTS: Record<string, string> = { www: "www.wrike.com", us: "www.wrike.com", eu: "app-eu.wrike.com", us2: "app-us2.wrike.com" };

// "<token>", or where the account lives first: "eu:<token>", "app-eu.wrike.com <token>", a link into Wrike and the token
export function parseKey(raw: string) {
  const s = raw.trim();
  const m = /^(?:https?:\/\/)?([\w.-]+?)(?:\/\S*)?[\s:]+(\S+)$/.exec(s);
  if (!m) return { host: HOSTS.www!, token: s, region: false };
  const where = m[1]!.toLowerCase();
  const host = where.includes(".") ? where : (HOSTS[where] ?? `app-${where.replace(/^app-/, "")}.wrike.com`);
  // only Wrike's own hosts: the key decides where the token is sent
  if (!/^(www|app-[a-z0-9]+)\.wrike\.com$/.test(host)) throw new AppsError(`${m[1]} isn't a Wrike address: paste the token alone, or with eu: or us2: in front`);
  return { host, token: m[2]!, region: true };
}

export const api: Api = {
  name: "Wrike",
  base: "https://www.wrike.com/api/v4",
  tokenHelp: "Wrike → your picture → Apps & Integrations → API → Permanent access token",
  auth: (key) => ({ Authorization: `Bearer ${parseKey(key).token}` }),
  url: (key, _base, path) => `https://${parseKey(key).host}/api/v4${path}`,
};

const ME = { method: "GET", path: "/contacts", query: ["me"], headers: [] };
type Me = { data?: { firstName?: string; lastName?: string; profiles?: { email?: string }[] }[] };

const file = new URL("./actions.json", import.meta.url);
const actions = await specActions(file, api);
// lists and objects go to Wrike as JSON text (responsibles=["KUAAAA"]), the way it reads them
for (const { name, json } of (await Bun.file(file).json()).actions as { name: string; json?: string[] }[]) {
  if (!json) continue;
  const action = actions[name]!;
  const run = action.run;
  action.run = (input: Record<string, unknown>, key) =>
    run({ ...input, ...Object.fromEntries(json.filter((f) => input[f] !== undefined).map((f) => [f, JSON.stringify(input[f])])) }, key);
}
// a downloaded file keeps its name rather than "download"
for (const name of ["get_attachments_download", "get_attachments_preview"]) {
  const action = actions[name]!;
  const run = action.run;
  action.run = async (input: { attachmentId: string }, key) => {
    const [got, info] = await Promise.all([run(input, key), call(api, key, { method: "GET", path: "/attachments/{attachmentId}", query: [], headers: [] }, input).catch(() => null)]);
    const real = (info as { data?: { name?: string }[] } | null)?.data?.[0]?.name;
    return got instanceof AppFile && real ? new AppFile(real, got.mimetype, got.bytes) : got;
  };
}

const form = (method: string, path: string, fields: string[] = []): Send => ({ method, path, query: [], headers: [], ...(fields.length && { body: { kind: "urlencoded" as const, fields: fields.map((f): [string, string] => [f, f]) } }) });
// a header can only carry plain characters
const headerSafe = (name: string) => name.replace(/[^\x20-\x7e]+/g, encodeURIComponent);

// a file from the computer, sent as itself with its name in X-File-Name
const upload = (method: string, path: string, id: string, idHelp: string, description: string): OwnAction => ({
  description,
  input: z.object({ [id]: z.string().describe(idHelp), file: z.any().describe('The file from the computer: {"file": "/work/report.pdf"}') }),
  run: (i: Record<string, unknown>, key: string) => {
    if (!(i.file instanceof AppFile)) throw new AppsError('file: give the file as {"file": "/work/report.pdf"}');
    return call(api, key, { method, path, query: [], headers: [["file_name", "X-File-Name"]], body: { kind: "file", field: "file" } }, { ...i, file_name: headerSafe(i.file.name) });
  },
});

const HOOK = {
  hookUrl: z.string().describe("The address Wrike sends events to: https, port 80 or 443, reachable from the internet"),
  secret: z.string().optional().describe("A secret Wrike signs each event with (X-Hook-Signature, an HMAC-SHA256 of the body). Wrike first checks the address answers its handshake"),
  events: z.array(z.string()).optional().describe("Only these events, like [\"TaskCreated\", \"CommentAdded\"]; all of them if left out"),
  parameterisedEvents: z.array(z.record(z.string(), z.any())).optional().describe('Events with filters, like [{"event": "TaskCustomFieldChanged", "customFields": ["IEAAAAADJUAAAABB"], "fields": ["title"]}]. An event can\'t be in both lists'),
  customItemTypes: z.array(z.string()).optional().describe("Only items of these custom item types (their ids)"),
};
type HookInput = { hookUrl: string; secret?: string; events?: string[]; parameterisedEvents?: unknown[]; customItemTypes?: string[]; recursive?: boolean; folderId?: string; spaceId?: string };
const makeHook = (path: string) => (i: HookInput, key: string) =>
  call(api, key, form("POST", path, Object.keys(i).filter((k) => k !== "folderId" && k !== "spaceId")), {
    ...i,
    ...(i.events && { events: `[${i.events.join(",")}]` }),
    ...(i.parameterisedEvents && { parameterisedEvents: JSON.stringify(i.parameterisedEvents) }),
    ...(i.customItemTypes && { customItemTypes: JSON.stringify(i.customItemTypes) }),
  });
const WEBHOOK_ID = z.string().describe("The webhook's id (get_all_webhooks lists them)");

const hand: Record<string, OwnAction> = {
  get_all_webhooks: { description: "The webhooks this Wrike token has made: id, address (hookUrl), folder or space, and whether Active or Suspended.", readOnly: true, input: z.object({}), run: (_i, key) => call(api, key, form("GET", "/webhooks"), {}) },
  get_webhook_by_id: { description: "One or more Wrike webhooks by id (up to 100, comma separated): address, scope and status.", readOnly: true, input: z.object({ webhookIds: z.string().describe("Webhook ids, comma separated") }), run: (i, key) => call(api, key, form("GET", "/webhooks/{webhookIds}"), i) },
  create_account_webhooks: { description: "Have Wrike send events about the whole account (tasks, folders, projects, comments, files, time, approvals) to an address.", input: z.object(HOOK), run: makeHook("/webhooks") },
  create_folder_webhook: { description: "Have Wrike send events about one folder or project (and, with recursive, everything inside it) to an address.", input: z.object({ folderId: z.string().describe("The folder's or project's id"), ...HOOK, recursive: z.boolean().optional().describe("Also subfolders and subprojects, anywhere below") }), run: makeHook("/folders/{folderId}/webhooks") },
  create_space_webhook: { description: "Have Wrike send events about one space to an address.", input: z.object({ spaceId: z.string().describe("The space's id (list_spaces lists them)"), ...HOOK }), run: makeHook("/spaces/{spaceId}/webhooks") },
  update_webhook_state: { description: "Pause (Suspended) or resume (Active) a Wrike webhook. Wrike suspends one by itself when deliveries fail.", input: z.object({ webhookId: WEBHOOK_ID, status: z.enum(["Active", "Suspended"]).describe("Active to resume, Suspended to pause") }), run: (i, key) => call(api, key, form("PUT", "/webhooks/{webhookId}", ["status"]), i) },
  delete_webhook: { description: "Delete a Wrike webhook. Emplio's own (its address has /webhooks/app/wrike/) runs automations: removing the automations removes it.", input: z.object({ webhookId: WEBHOOK_ID }), run: (i, key) => call(api, key, form("DELETE", "/webhooks/{webhookId}"), i) },
  upload_task_attachment: upload("POST", "/tasks/{taskId}/attachments", "taskId", "The task's id", "Attach a file from the computer to a Wrike task (create_task_attachment attaches one from a link instead)."),
  upload_folder_attachment: upload("POST", "/folders/{folderId}/attachments", "folderId", "The folder's or project's id", "Attach a file from the computer to a Wrike folder or project."),
  upload_attachment_version: upload("PUT", "/attachments/{attachmentId}", "attachmentId", "The attachment's id (get_tasks_attachments lists a task's files)", "Upload a new version of a file already attached in Wrike; the old one stays in its history."),
};

export const wrike: OwnApp = {
  app: "wrike",
  name: "Wrike",
  logo: "/logos/wrike.svg",
  keyField: {
    label: "Permanent access token",
    help: "In Wrike, click your picture (top right) → Apps & Integrations → API. Create a new app (any name, like Emplio), then under Permanent access token click Create token, confirm with your password and copy it. Pick the address you open Wrike at. Emplio can then see and change whatever your Wrike user can.",
    placeholder: "eyJ0dCI6InAi...",
    sep: ":",
    parts: [{label:"Wrike address",optional:true,options:[{value:"",label:"app.wrike.com"},{value:"eu",label:"app-eu.wrike.com"},{value:"us2",label:"app-us2.wrike.com"}]},{label:"Permanent access token",secret:true,placeholder:"eyJ0dCI6InAi..."}],
  },
  async check(key) {
    const { host, token, region } = parseKey(key);
    const who = (me: Me) => {
      const p = me.data?.[0];
      const name = [p?.firstName, p?.lastName].filter(Boolean).join(" ") || p?.profiles?.[0]?.email || "Wrike";
      return host === HOSTS.www ? name : `${name} (${host})`;
    };
    try {
      return who((await call(api, key, ME, { me: true })) as Me);
    } catch (e) {
      if (region || !(e instanceof AppsError && e.expired)) throw e;
      // a token from another data centre is refused here: say where it works
      for (const [prefix, other] of [["eu", HOSTS.eu!], ["us2", HOSTS.us2!]]) {
        const ok = await call(api, `${prefix}:${token}`, ME, { me: true }).then(() => true, () => false);
        if (ok) throw new AppsError(`That token is for Wrike's ${other} data centre: paste it as ${prefix}: followed by the token`);
      }
      throw e;
    }
  },
  push: {
    events,
    triggers,
    start: (key, connection, _event, config) => watch(api, key, connection, config),
    stop: (key, id) => unwatch(api, key, id),
    receive: (delivery, key) => receive(api, delivery, key),
    wanted,
  },
  actions: { ...actions, ...hand },
};
